'use client';

import React, { useState, useEffect } from 'react';
import { usePackages } from '@/context/PackageContext';
import { Plus, Edit, Trash2, X, Check, ArrowLeft } from 'lucide-react';
import Button from '@/components/ui/Button';
import Link from 'next/link';
import { useRouter } from 'next/navigation';

const AdminDashboard = () => {
    const { packages, addPackage, updatePackage, deletePackage } = usePackages();
    const router = useRouter();
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [currentPackage, setCurrentPackage] = useState(null); // null for add, object for edit

    // Simple auth check simulation
    useEffect(() => {
        // In a real app, check for token/cookie
        const isAdmin = localStorage.getItem('flight99_admin_auth');
        if (!isAdmin) {
            router.push('/admin/login');
        }
    }, [router]);

    const handleOpenModal = (pkg = null) => {
        setCurrentPackage(pkg);
        setIsModalOpen(true);
    };

    const handleDelete = (id) => {
        if (confirm('Are you sure you want to delete this package?')) {
            deletePackage(id);
        }
    };

    return (
        <div className="min-h-screen bg-gray-50 p-6 md:p-12">
            <div className="max-w-7xl mx-auto">
                <div className="flex justify-between items-center mb-8">
                    <div className="flex items-center gap-4">
                        <Link href="/" className="p-2 bg-white rounded-full shadow-sm text-gray-600 hover:text-primary transition-colors">
                            <ArrowLeft className="w-5 h-5" />
                        </Link>
                        <div>
                            <h1 className="text-3xl font-bold text-gray-900">Admin Dashboard</h1>
                            <p className="text-gray-500">Manage your holiday packages</p>
                        </div>
                    </div>
                    <Button onClick={() => handleOpenModal()} variant="primary" className="flex items-center gap-2">
                        <Plus className="w-4 h-4" /> Add Package
                    </Button>
                </div>

                {/* Packages Table */}
                <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
                    <table className="w-full text-left">
                        <thead className="bg-gray-50 border-b border-gray-100">
                            <tr>
                                <th className="p-4 font-semibold text-gray-600">Title</th>
                                <th className="p-4 font-semibold text-gray-600">Location</th>
                                <th className="p-4 font-semibold text-gray-600">Price</th>
                                <th className="p-4 font-semibold text-gray-600">Type</th>
                                <th className="p-4 font-semibold text-gray-600 text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {packages.map((pkg) => (
                                <tr key={pkg.id} className="hover:bg-gray-50/50 transition-colors">
                                    <td className="p-4 font-medium text-gray-900">{pkg.title}</td>
                                    <td className="p-4 text-gray-500">{pkg.location}</td>
                                    <td className="p-4 text-primary font-bold">₹{pkg.price.toLocaleString()}</td>
                                    <td className="p-4">
                                        <span className={`px-2 py-1 rounded text-xs font-semibold ${pkg.type === 'International' ? 'bg-blue-50 text-blue-600' : 'bg-green-50 text-green-600'}`}>
                                            {pkg.type}
                                        </span>
                                    </td>
                                    <td className="p-4 text-right">
                                        <div className="flex justify-end gap-2">
                                            <button onClick={() => handleOpenModal(pkg)} className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors">
                                                <Edit className="w-4 h-4" />
                                            </button>
                                            <button onClick={() => handleDelete(pkg.id)} className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors">
                                                <Trash2 className="w-4 h-4" />
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                    {packages.length === 0 && (
                        <div className="p-12 text-center text-gray-500">
                            No packages found. Add one to get started.
                        </div>
                    )}
                </div>
            </div>

            {/* Edit/Add Modal */}
            {isModalOpen && (
                <PackageFormModal
                    isOpen={isModalOpen}
                    onClose={() => setIsModalOpen(false)}
                    packageData={currentPackage}
                    onSubmit={(data) => {
                        if (currentPackage) {
                            updatePackage(currentPackage.id, data);
                        } else {
                            addPackage(data);
                        }
                        setIsModalOpen(false);
                    }}
                />
            )}
        </div>
    );
};

const PackageFormModal = ({ isOpen, onClose, packageData, onSubmit }) => {
    if (!isOpen) return null;

    const [formData, setFormData] = useState({
        title: '',
        location: '',
        price: '',
        type: 'International', // Default
        duration: '',
        description: '',
        image: 'https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?q=80&w=2070&auto=format&fit=crop', // Placeholder
        ...packageData
    });

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        // Convert price to number
        onSubmit({ ...formData, price: Number(formData.price) });
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
            <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto">
                <div className="p-6 border-b border-gray-100 flex justify-between items-center sticky top-0 bg-white z-10">
                    <h2 className="text-xl font-bold text-gray-900">{packageData ? 'Edit Package' : 'Add New Package'}</h2>
                    <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><X className="w-5 h-5" /></button>
                </div>

                <form onSubmit={handleSubmit} className="p-6 space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Package Title</label>
                            <input type="text" name="title" required value={formData.title} onChange={handleChange} className="input-premium w-full" placeholder="e.g. Magical Maldives" />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Location</label>
                            <input type="text" name="location" required value={formData.location} onChange={handleChange} className="input-premium w-full" placeholder="e.g. Male, Maldives" />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Price (₹)</label>
                            <input type="number" name="price" required value={formData.price} onChange={handleChange} className="input-premium w-full" placeholder="50000" />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Type</label>
                            <select name="type" value={formData.type} onChange={handleChange} className="input-premium w-full">
                                <option value="International">International</option>
                                <option value="Domestic">Domestic</option>
                            </select>
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Duration</label>
                            <input type="text" name="duration" required value={formData.duration} onChange={handleChange} className="input-premium w-full" placeholder="e.g. 4 Days / 3 Nights" />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Image URL</label>
                            <input type="text" name="image" required value={formData.image} onChange={handleChange} className="input-premium w-full" placeholder="https://..." />
                        </div>
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Description</label>
                        <textarea name="description" rows="4" required value={formData.description} onChange={handleChange} className="input-premium w-full resize-none" placeholder="Detailed description..." />
                    </div>

                    <div className="pt-4 flex justify-end gap-3">
                        <Button type="button" variant="outline" onClick={onClose}>Cancel</Button>
                        <Button type="submit" variant="primary">Save Package</Button>
                    </div>
                </form>
            </div>
        </div>
    );
};

export default AdminDashboard;
